UPDATE device_command_request
   SET status = #{command.status}, failure_code = #{command.failureCode},
       dispatched_at = #{command.dispatchedAt}, acknowledged_at = #{command.acknowledgedAt},
       completed_at = #{command.completedAt}, status_updated_at = #{command.statusUpdatedAt},
       version = #{command.version}
 WHERE command_id = #{command.commandId} AND version = #{expectedVersion}
